// <auto-generated />
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import type { UseQueryOptions, UseMutationOptions } from '@tanstack/react-query';
import { useApiService } from './useApiService';
import { ApiError } from '../errors/ApiError';
import type { ExceptionTestResponse } from '../models';

const testingKeys = {
  all: ['testing'] as const,
  getExceptionTest: (code: number) => [...testingKeys.all, 'getExceptionTest', code] as const,
};

export { testingKeys };

/** Test exception handling */
export function useGetExceptionTest(code: number, options?: Omit<UseQueryOptions<ExceptionTestResponse, ApiError>, 'queryKey' | 'queryFn'>) {
  const api = useApiService();
  return useQuery({
    queryKey: testingKeys.getExceptionTest(code),
    queryFn: async () => {
      const result = await api.testing.getExceptionTest(code);
      if (result.status === 'ok') {
        return result.data;
      }
      if ('error' in result && result.error instanceof ApiError) {
        throw result.error;
      }
      throw new ApiError(
        result.response.status,
        result.response.statusText,
        'error' in result ? result.error.message : 'Request failed',
        result.response,
      );
    },
    enabled: !!code,
    retry: false,
    ...options,
  });
}

/** Test error responses */
export function useGetErrorResponseTest(options?: Omit<UseMutationOptions<void, ApiError, number>, 'mutationFn'>) {
  const api = useApiService();
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: async (status: number) => {
      const result = await api.testing.getErrorResponseTest(status);
      if (result.status === 'noContent') {
        return;
      }
      if ('error' in result && result.error instanceof ApiError) {
        throw result.error;
      }
      throw new ApiError(
        result.response.status,
        result.response.statusText,
        'error' in result ? result.error.message : 'Request failed',
        result.response,
      );
    },
    ...options,
    onSuccess: (data, variables, onMutateResult, context) => {
      queryClient.invalidateQueries({ queryKey: testingKeys.all });
      options?.onSuccess?.(data, variables, onMutateResult, context);
    },
  });
}